<?php
/** Plugin Name: TEMP PS S1724g deploy petshop-cf-ip v1.0. Fazes: 1 lint, 2 deploy+heartbeat, 3 patikra (simuliuotas CF IP), 9 pasalinti */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1724g'])) return; $f=(string)$_GET['ps_s1724g']; $r=['v'=>'S1724g','faze'=>$f]; @set_time_limit(120);
  $B=''; $plug=WPMU_PLUGIN_DIR.'/petshop-cf-ip.php';
  $tok=function($code){ try{ token_get_all($code,TOKEN_PARSE); return 'ok'; }catch(Throwable $e){ return 'KLAIDA '.$e->getMessage(); } };
  $hb=function(){ for($i=0;$i<2;$i++){ $x=wp_remote_get(home_url('/?ps_hb='.time()),['timeout'=>25,'sslverify'=>false]); $c=is_wp_error($x)?'ERR '.$x->get_error_message():wp_remote_retrieve_response_code($x); if($c===200) return 200; sleep(2);} return $c; };
  try{
    if($f==='1'){ $r['lint']=$tok(base64_decode($B)); $r['yra']=file_exists($plug); $r['remote_addr']=$_SERVER['REMOTE_ADDR']??null; $r['cf_hdr']=$_SERVER['HTTP_CF_CONNECTING_IP']??null; }
    if($f==='2'){ $code=base64_decode($B); if($tok($code)!=='ok') throw new Exception('lint'); file_put_contents($plug,$code); $r['md5']=md5_file($plug); $r['heartbeat']=$hb(); if($r['heartbeat']!==200){ unlink($plug); $r['ROLLBACK']='pasalintas'; } }
    if($f==='3'){ $r['md5']=file_exists($plug)?md5_file($plug):'NERA'; $r['f_yra']=function_exists('ps_cf_ip_apply'); $r['remote_addr']=$_SERVER['REMOTE_ADDR']??null; $r['edge']=$_SERVER['PS_CF_EDGE_IP']??null;
      // simuliacija: CF IP + antraste
      $bak=$_SERVER; $_SERVER['REMOTE_ADDR']='172.71.5.5'; $_SERVER['HTTP_CF_CONNECTING_IP']='85.206.1.1'; ps_cf_ip_apply(); $r['sim_cf']=[$_SERVER['REMOTE_ADDR'],$_SERVER['PS_CF_EDGE_IP']??null]; $_SERVER=$bak;
      $bak=$_SERVER; $_SERVER['REMOTE_ADDR']='1.2.3.4'; $_SERVER['HTTP_CF_CONNECTING_IP']='85.206.1.1'; unset($_SERVER['PS_CF_EDGE_IP']); ps_cf_ip_apply(); $r['sim_ne_cf']=[$_SERVER['REMOTE_ADDR'],$_SERVER['PS_CF_EDGE_IP']??null]; $_SERVER=$bak;
      $r['heartbeat']=$hb(); }
    if($f==='9'){ if(file_exists($plug)){ unlink($plug); $r['pasalintas']=true; } $r['heartbeat']=$hb(); }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE); exit;
}, 1);
